import{_ as a,o as t,c as s,a7 as o,ar as r,as as i,at as l,au as d,av as c}from"./chunks/framework.DLZEy9Ii.js";const v=JSON.parse('{"title":"Music Free Serve 集成","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"serve.md","filePath":"serve.md"}'),n={name:"serve.md"};function h(p,e,_,m,g,u){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="music-free-serve-集成" tabindex="-1">Music Free Serve 集成 <a class="header-anchor" href="#music-free-serve-集成" aria-label="Permalink to “Music Free Serve 集成”">​</a></h1><p>相关文档：<a href="/music-free-site/playlist.html">歌单</a> · <a href="/music-free-site/share.html">音乐分享</a> · <a href="/music-free-site/user.html">用户</a></p><h2 id="_1-模块概述" tabindex="-1">1. 模块概述 <a class="header-anchor" href="#_1-模块概述" aria-label="Permalink to “1. 模块概述”">​</a></h2><p><strong>MusicFreeServe 集成</strong>（<code>server-sdk</code>）让 MusicFree 作为 <a href="https://github.com/AnsGoo/music-free-serve" target="_blank" rel="noreferrer">music-free-serve</a> 的客户端，实现<strong>歌单同步、共享、订阅</strong>与<strong>远程发现库</strong>浏览。所有能力都需要先在「用户配置」中配置并启用 serve。</p><p>集成后，歌单页新增 <code>发现歌单</code> / <code>共享歌单</code> 页签与 <code>推荐</code> 页，音乐分享也会复用同一套 serve 凭据进行引导。</p><p><img src="'+r+'" alt=""></p><h2 id="_2-配置-用户配置页" tabindex="-1">2. 配置（用户配置页） <a class="header-anchor" href="#_2-配置-用户配置页" aria-label="Permalink to “2. 配置（用户配置页）”">​</a></h2><p>在 <code>/settings</code>（用户配置）中填写：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><code>serve.enabled</code></td><td>是否启用与 serve 的集成</td></tr><tr><td><code>serve.host_url</code></td><td>music-free-serve 的访问地址（<code>HOST_URL</code>）</td></tr><tr><td><code>serve.api_key</code></td><td>serve 的 API Key</td></tr><tr><td><code>serve.listen_record</code></td><td>是否上报听歌记录</td></tr><tr><td><code>serve.sync_playlist</code></td><td>是否将本用户的公开歌单同步到 serve</td></tr></tbody></table><ul><li>支持<strong>实时检测连通性</strong>：填写地址与 API Key 后可即时测试。</li><li>未启用时，歌单页默认落到「我的歌单」，推荐 / 发现 / 共享页签显示为空。</li></ul><p><img src="'+i+'" alt=""></p><h2 id="_3-歌单同步" tabindex="-1">3. 歌单同步 <a class="header-anchor" href="#_3-歌单同步" aria-label="Permalink to “3. 歌单同步”">​</a></h2><p>开启 <code>serve.sync_playlist</code> 后：</p><ul><li>用户的<strong>公开歌单</strong>（<code>is_public=1</code>）会推送 / 更新 / 删除到 serve；</li><li>本地与远程歌单 ID 的映射自动维护；</li><li>除增量同步外，服务端每 <strong>8 小时</strong> 执行一次全量对账兜底。</li></ul><blockquote><p>共享中的歌单即使未设为公开，也会被同步到 serve（用于生成分享），见 <a href="#_4-歌单共享">4</a>。</p></blockquote><p><img src="'+l+'" alt=""></p><h2 id="_4-歌单共享" tabindex="-1">4. 歌单共享 <a class="header-anchor" href="#_4-歌单共享" aria-label="Permalink to “4. 歌单共享”">​</a></h2><p>在歌单详情页可开启「共享」：</p><ul><li><strong>可见性</strong>：<code>unlisted</code>（仅凭共享码）或 <code>public</code>（公开可见）；</li><li><strong>共享码</strong>：开启后自动生成，可复制分享；</li><li><strong>只读</strong>：共享中的歌单不可编辑，需先关闭共享；</li><li>关闭共享会作废共享码并清理远程订阅关系。</li></ul><p><img src="'+d+'" alt=""></p><h2 id="_5-订阅-接收方" tabindex="-1">5. 订阅（接收方） <a class="header-anchor" href="#_5-订阅-接收方" aria-label="Permalink to “5. 订阅（接收方）”">​</a></h2><h3 id="_5-1-共享歌单-共享码" tabindex="-1">5.1 共享歌单 / 共享码 <a class="header-anchor" href="#_5-1-共享歌单-共享码" aria-label="Permalink to “5.1 共享歌单 / 共享码”">​</a></h3><ul><li>「共享歌单」页签浏览 serve 上的公开共享歌单，支持搜索、分页与订阅；</li><li>「共享码订阅」输入共享码可直接解析并订阅（含 <code>unlisted</code> 歌单）；</li><li>订阅会在本地生成 <code>external_source=serve-shared</code> 的只读副本。</li></ul><h3 id="_5-2-发现歌单" tabindex="-1">5.2 发现歌单 <a class="header-anchor" href="#_5-2-发现歌单" aria-label="Permalink to “5.2 发现歌单”">​</a></h3><p>「发现歌单」页签浏览 serve 发现库的平台 / 分类 / 歌单，支持关键词检索；订阅后导入为 <code>external_source=serve-discovery</code> 的本地只读歌单，并按标题 + 艺术家匹配曲库。</p><p><img src="'+c+'" alt=""></p><h3 id="_5-3-远程关闭共享" tabindex="-1">5.3 远程关闭共享 <a class="header-anchor" href="#_5-3-远程关闭共享" aria-label="Permalink to “5.3 远程关闭共享”">​</a></h3><p>若远程关闭共享或删除歌单，本地订阅副本会在打开或「同步」时自动<strong>转为自有可编辑歌单</strong>，不会变成死链。</p><h2 id="_6-推荐页" tabindex="-1">6. 推荐页 <a class="header-anchor" href="#_6-推荐页" aria-label="Permalink to “6. 推荐页”">​</a></h2><p>歌单页默认进入 <strong>推荐</strong> 页签：</p><ul><li><strong>热门歌单</strong>：聚合各平台热度榜单（实时拉取，不缓存）；</li><li><strong>推荐歌单</strong>：公开共享歌单预览，可跳转到「共享歌单」页签。</li></ul><p><img src="'+r+'" alt=""></p><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to “7. 常见问题”">​</a></h2><p><strong>Q：推荐 / 共享 / 发现歌单为空？</strong><br> A：先确认已在「用户配置」启用并正确配置 serve，且远程服务可达。</p><p><strong>Q：共享中的歌单为什么不能编辑？</strong><br> A：为保证本地与远程一致会锁定编辑，请先关闭共享。</p><p><strong>Q：未启用 serve 会影响本地歌单吗？</strong><br> A：不会。本地自建 / 导入 / 文件夹歌单照常使用，仅远程相关页签为空。</p>',36)])])}const f=a(n,[["render",h]]);export{v as __pageData,f as default};
